// Behaviour test for 00c18b20: PKCTRRedblackTree InsertFixup -- after each plain BST insert of a red node, the fixup (recolour / rotate through the nil sentinel) must leave a valid red-black tree
#include <cstdio>

struct RbNode {
    RbNode* Left;
    RbNode* Right;
    RbNode* Parent;
    long    Colour;
    void* Key;
    long  KeyValue;
};
enum { BLACK = 0, RED = 1 };

class Tree {
public:
    virtual ~Tree() { }
    void* PAllocator;
    void* POwnedAllocator;
    RbNode Sentinel;
    RbNode* Root;
    long Count;
    Tree() : Root(&Sentinel), Count(0)
    {
        Sentinel.Left = Sentinel.Right = &Sentinel;
        Sentinel.Parent = 0;
        Sentinel.Colour = BLACK;
    }
    void RotateLeft(RbNode* x)
    {
        RbNode* y = x->Right;
        x->Right = y->Left;
        if (y->Left != &Sentinel) y->Left->Parent = x;
        if (y != &Sentinel) y->Parent = x->Parent;
        if (x->Parent) {
            if (x == x->Parent->Left) x->Parent->Left = y;
            else x->Parent->Right = y;
        } else {
            Root = y;
        }
        y->Left = x;
        if (x != &Sentinel) x->Parent = y;
    }
    void RotateRight(RbNode* x)
    {
        RbNode* y = x->Left;
        x->Left = y->Right;
        if (y->Right != &Sentinel) y->Right->Parent = x;
        if (y != &Sentinel) y->Parent = x->Parent;
        if (x->Parent) {
            if (x == x->Parent->Right) x->Parent->Right = y;
            else x->Parent->Left = y;
        } else {
            Root = y;
        }
        y->Right = x;
        if (x != &Sentinel) x->Parent = y;
    }
    void InsertFixup(RbNode* x)
    {
        while (x != Root && x->Parent->Colour == RED) {
            if (x->Parent == x->Parent->Parent->Left) {
                RbNode* y = x->Parent->Parent->Right;
                if (y->Colour == RED) {
                    x->Parent->Colour = BLACK;
                    y->Colour = BLACK;
                    x->Parent->Parent->Colour = RED;
                    x = x->Parent->Parent;
                } else {
                    if (x == x->Parent->Right) {
                        x = x->Parent;
                        RotateLeft(x);
                    }
                    x->Parent->Colour = BLACK;
                    x->Parent->Parent->Colour = RED;
                    RotateRight(x->Parent->Parent);
                }
            } else {
                RbNode* y = x->Parent->Parent->Left;
                if (y->Colour == RED) {
                    x->Parent->Colour = BLACK;
                    y->Colour = BLACK;
                    x->Parent->Parent->Colour = RED;
                    x = x->Parent->Parent;
                } else {
                    if (x == x->Parent->Left) {
                        x = x->Parent;
                        RotateRight(x);
                    }
                    x->Parent->Colour = BLACK;
                    x->Parent->Parent->Colour = RED;
                    RotateLeft(x->Parent->Parent);
                }
            }
        }
        Root->Colour = BLACK;
    }
