            if (x->Parent == x->Parent->Parent->Left) {
                RbNode* y = x->Parent->Parent->Right;
                if (y->Colour == RED) {
                    x->Parent->Colour = BLACK;
                    y->Colour = BLACK;
                    x->Parent->Parent->Colour = RED;
                    x = x->Parent->Parent;
